// Kit posts { subscriber: { id, first_name, email_address, state, ... } }
const body = $input.first().json.body ?? $input.first().json;
const s = body.subscriber ?? {};
if (!s.email_address) {
  throw new Error('No subscriber in payload — was this called by Kit? Payload: ' + JSON.stringify(body).slice(0, 300));
}
return [{
  json: {
    subscriber_id: s.id ?? null,
    email: s.email_address,
    first_name: (s.first_name ?? '').trim(),
    greeting: (s.first_name ?? '').trim() || 'there',
  },
}];
